const _solve = function solve(){
  // Houses are indexed 0-4
  // Each attribute set:
  const colors = ['red', 'green', 'ivory', 'yellow', 'blue'];
  const nationals = ['Englishman', 'Spaniard', 'Ukrainian', 'Norwegian', 'Japanese'];
  const pets = ['dog', 'snail', 'fox', 'horse', 'zebra'];
  const beverages = ['coffee', 'tea', 'milk', 'orange juice', 'water'];
  const hobbies = ['dancing', 'painting', 'reading', 'football', 'chess'];

  // Generate all permutations
  function* perms(arr) {
    const a = [...arr];
    yield* heapPerms(a, a.length);
  }

  function* heapPerms(a, n) {
    if (n === 1) { yield [...a]; return; }
    for (let i = 0; i < n - 1; i++) {
      yield* heapPerms(a, n - 1);
      const j = n % 2 === 0 ? i : 0;
      [a[j], a[n - 1]] = [a[n - 1], a[j]];
    }
    yield* heapPerms(a, n - 1);
  }

  function idxOf(perm, val) { return perm.indexOf(val); }

  // Constraint 6: green is immediately to the right of ivory => green = ivory + 1
  // Constraint 9: house 2 (middle, index 2) drinks milk
  // Constraint 10: Norwegian in house 0

  for (const color of perms(colors)) {
    // Constraint 6: green immediately right of ivory
    const greenIdx = idxOf(color, 'green');
    const ivoryIdx = idxOf(color, 'ivory');
    if (greenIdx !== ivoryIdx + 1) continue;

    for (const nat of perms(nationals)) {
      // Constraint 10: Norwegian first house
      if (nat[0] !== 'Norwegian') continue;
      // Constraint 2: Englishman in red house
      if (idxOf(nat, 'Englishman') !== idxOf(color, 'red')) continue;
      // Constraint 15: Norwegian next to blue house
      const norIdx = 0;
      const blueIdx = idxOf(color, 'blue');
      if (Math.abs(norIdx - blueIdx) !== 1) continue;

      for (const bev of perms(beverages)) {
        // Constraint 9: middle house (index 2) drinks milk
        if (bev[2] !== 'milk') continue;
        // Constraint 4: green house drinks coffee
        if (bev[greenIdx] !== 'coffee') continue;
        // Constraint 5: Ukrainian drinks tea
        if (bev[idxOf(nat, 'Ukrainian')] !== 'tea') continue;

        for (const hob of perms(hobbies)) {
          // Constraint 8: yellow house is a painter
          if (hob[idxOf(color, 'yellow')] !== 'painting') continue;
          // Constraint 13: football player drinks orange juice
          if (idxOf(hob, 'football') !== idxOf(bev, 'orange juice')) continue;
          // Constraint 14: Japanese person plays chess
          if (hob[idxOf(nat, 'Japanese')] !== 'chess') continue;

          for (const pet of perms(pets)) {
            // Constraint 3: Spaniard owns dog
            if (pet[idxOf(nat, 'Spaniard')] !== 'dog') continue;
            // Constraint 7: snail owner likes dancing
            if (idxOf(pet, 'snail') !== idxOf(hob, 'dancing')) continue;
            // Constraint 11: reading next to fox
            const readIdx = idxOf(hob, 'reading');
            const foxIdx = idxOf(pet, 'fox');
            if (Math.abs(readIdx - foxIdx) !== 1) continue;
            // Constraint 12: painter next to horse
            const paintIdx = idxOf(hob, 'painting');
            const horseIdx = idxOf(pet, 'horse');
            if (Math.abs(paintIdx - horseIdx) !== 1) continue;

            // All constraints satisfied!
            const waterIdx = idxOf(bev, 'water');
            const zebraIdx = idxOf(pet, 'zebra');
            return {
              water: nat[waterIdx],
              zebra: nat[zebraIdx]
            };
          }
        }
      }
    }
  }
  return null; // no solution found
};

